/// <summary>
/// The <c>METCustFreeInvoiceWorkflowCancelManager_Extension</c> class manages validation if bulk workflow selected is set to yes.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
[ExtensionOf(classStr(CustFreeInvoiceWorkflowCancelManager))]
final class METCustFreeInvoiceWorkflowCancelManager_Extension
{
}

Method.Source:
/// <summary>
/// Contains the code that does the actual job of the class.
/// </summary>
/// <param name="_args">
/// The arguments for the <c>WorkflowCancelManager</c> class.
/// </param>
/// <remarks>
/// The update document override will be invoked for the derived classes to update the state of the
/// underlying workflow document.
/// </remarks>
public void run(Args _args)
{
    CustInvoiceTable custInvoiceTable;

    if (_args.record() is CustInvoiceTable)
    {
        custInvoiceTable = _args.record() as CustInvoiceTable;

        if (custInvoiceTable.METBulkWorkflowSelected)
        {
            throw Error("@MET:METFTIBulkWFSelectedValid");
        }
    }
    else if (_args.record() is WorkflowTrackingStatusTable)
    {
        WorkflowTrackingStatusTable workflowTrackingStatusTable = _args.record() as WorkflowTrackingStatusTable;

        if (workflowTrackingStatusTable.ContextTableId == tableNum(CustInvoiceTable))
        {
            custInvoiceTable = CustInvoiceTable::findRecId(workflowTrackingStatusTable.ContextRecId);

            if (custInvoiceTable.METBulkWorkflowSelected)
            {
                throw Error("@MET:METFTIBulkWFSelectedValid");
            }
        }
    }

    next run(_args);
}
